package httpapi

import (
	"github.com/gin-gonic/gin"
	swaggerFiles "github.com/swaggo/files"
	ginSwagger "github.com/swaggo/gin-swagger"

	// Registers the generated specification with gin-swagger. The package is
	// generated by `go tool swag init`; see cmd/server/main.go.
	_ "gin-clean-arch-demo/internal/adapter/httpapi/docs"
)

// registerDocs mounts the interactive Swagger UI and the raw documents it
// renders. The specification itself is generated from handler annotations, so
// there is no second copy to drift: swag writes
// internal/adapter/httpapi/docs/{docs.go,swagger.json,swagger.yaml}.
//
// A test asserts that every route the router serves is documented.
func (s *Server) registerDocs(r *gin.Engine) {
	r.GET("/docs/*any", ginSwagger.WrapHandler(swaggerFiles.Handler))
}
